fn boolean_op(ct: ClipType, subject: &Paths64, clip: &Paths64, fr: FillRule) -> Paths64 {
    let mut c = Clipper64::new();
    c.add_subject(subject.clone());
    if !clip.is_empty() {
        c.add_clip(clip.clone());
    }
    let mut sol = Paths64::new();
    c.execute(ct, fr, &mut sol);
    sol
}

fn union(paths: &Paths64, fr: FillRule) -> Paths64 {
    boolean_op(ClipType::Union, paths, &Paths64::new(), fr)
}

fn main() {
    let args: Vec<String> = std::env::args().collect();
    let complexity: i32 = if args.len() > 1 {
        match stoi(&args[1]) {
            Some(v) => std::cmp::min(v, 5),
            None => {
                // std::stoi threw -> terminate -> abort: no stdout, non-zero exit
                std::process::exit(134);
            }
        }
    } else {
        3
    };

    let geometry_layers = build_geometry_layers(complexity);

    // 1-3. per-layer union, accumulated
    let mut accumulated: Paths64 = Vec::new();
    for layer in &geometry_layers {
        let union_layer = union(layer, FillRule::EvenOdd);
        accumulated.extend(union_layer);
    }

    // 4. union of all layers
    let all_union = union(&accumulated, FillRule::EvenOdd);

    // 5-8. pairwise layer processing
    let mut processed: Paths64 = Vec::new();
    for i in 0..geometry_layers.len() {
        let layer_union = union(&geometry_layers[i], FillRule::EvenOdd);
        for j in (i + 1)..geometry_layers.len() {
            let other_union = union(&geometry_layers[j], FillRule::EvenOdd);
            let intersect = boolean_op(ClipType::Intersection, &layer_union, &other_union, FillRule::EvenOdd);
            let diff = boolean_op(ClipType::Difference, &layer_union, &other_union, FillRule::EvenOdd);
            let xorbit = boolean_op(ClipType::Xor, &layer_union, &other_union, FillRule::EvenOdd);
            processed.extend(intersect);
            processed.extend(diff);
            processed.extend(xorbit);
        }
    }

    // 9. union of processed
    let all_processed = union(&processed, FillRule::NonZero);

    // 10-13. offset sequence
    let offsets = [2.0f64, -1.5, 3.0, -2.0];
    let join_types = [JoinType::Round, JoinType::Miter, JoinType::Square, JoinType::Bevel];
    let mut offset_results: Paths64 = Vec::new();
    for i in 0..4 {
        let offset = inflate_paths(&all_processed, offsets[i], join_types[i], EndType::Polygon, 2.0, 0.0);
        offset_results.extend(offset);
    }

    // 14. union of offsets
    let union_offsets = union(&offset_results, FillRule::EvenOdd);

    // 15. interact with original union
    let final_intersect = boolean_op(ClipType::Intersection, &union_offsets, &all_union, FillRule::EvenOdd);
    let final_diff = boolean_op(ClipType::Difference, &union_offsets, &all_union, FillRule::EvenOdd);
    let final_xor = boolean_op(ClipType::Xor, &union_offsets, &all_union, FillRule::EvenOdd);

    // 16. combine
    let mut all_final: Paths64 = Vec::new();
    all_final.extend(final_intersect);
    all_final.extend(final_diff);
    all_final.extend(final_xor);

    // 17. final union
    let final_union = union(&all_final, FillRule::NonZero);

    // 18. translate normalize
    let bounds = get_bounds_paths(&final_union);
    let normalized = translate_paths(&final_union, -bounds.left, -bounds.top);

    // 19. final offset
    let last_offset = inflate_paths(&normalized, 1.0, JoinType::Round, EndType::Polygon, 2.0, 0.0);

    // 20. compute score
    let mut total_area = 0.0f64;
    let mut total_perimeter = 0.0f64;
    let mut total_vertices: i64 = 0;
    for path in &last_offset {
        total_area += area(path);
        total_vertices += path.len() as i64;
        if path.len() > 1 {
            for i in 0..path.len() {
                let j = (i + 1) % path.len();
                let dx = (path[j].x - path[i].x) as f64;
                let dy = (path[j].y - path[i].y) as f64;
                total_perimeter += (dx * dx + dy * dy).sqrt();
            }
        }
    }

    let complexity_score = total_area * 0.7 + total_perimeter * 0.2 + total_vertices as f64 * 0.1;

    println!("{}", format_g6(complexity_score));
}

