// Core geometry types and helpers mirroring Clipper2 clipper.core.h (v2.0.1).
#![allow(dead_code)]

pub const MAX_COORD: i64 = 2305843009213693951; // INT64_MAX / 4
pub const MIN_COORD: i64 = -MAX_COORD;
pub const INVALID: i64 = i64::MAX;
pub const UNINITIALIZED: f64 = -1.474e120;
pub const TOLERANCE: f64 = 1.0e-15;

#[derive(Clone, Copy, PartialEq, Eq, Debug, Default)]
pub struct Point64 {
    pub x: i64,
    pub y: i64,
}

impl Point64 {
    pub fn new(x: i64, y: i64) -> Point64 {
        Point64 { x, y }
    }
}

pub type Path64 = Vec<Point64>;
pub type Paths64 = Vec<Path64>;

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub struct Rect64 {
    pub left: i64,
    pub top: i64,
    pub right: i64,
    pub bottom: i64,
}

impl Rect64 {
    pub fn new(l: i64, t: i64, r: i64, b: i64) -> Rect64 {
        Rect64 { left: l, top: t, right: r, bottom: b }
    }
    pub fn is_valid(&self) -> bool {
        self.left != INVALID
    }
    pub fn width(&self) -> i64 {
        self.right - self.left
    }
    pub fn height(&self) -> i64 {
        self.bottom - self.top
    }
}

pub const INVALID_RECT64: Rect64 = Rect64 {
    left: i64::MAX,
    top: i64::MAX,
    right: i64::MIN,
    bottom: i64::MIN,
};

/// Clipper2 Area(Path64): a += (double)(prev.y + cur.y) * (double)(prev.x - cur.x); return a * 0.5
pub fn area(path: &Path64) -> f64 {
    let cnt = path.len();
    if cnt < 3 {
        return 0.0;
    }
    let mut a = 0.0f64;
    let mut prev = cnt - 1;
    for cur in 0..cnt {
        a += ((path[prev].y + path[cur].y) as f64) * ((path[prev].x - path[cur].x) as f64);
        prev = cur;
    }
    a * 0.5
}

pub fn is_positive(path: &Path64) -> bool {
    area(path) >= 0.0
}

pub fn get_bounds_paths(paths: &Paths64) -> Rect64 {
    let mut result = INVALID_RECT64;
    for path in paths {
        for p in path {
            if p.x < result.left {
                result.left = p.x;
            }
            if p.x > result.right {
                result.right = p.x;
            }
            if p.y < result.top {
                result.top = p.y;
            }
            if p.y > result.bottom {
                result.bottom = p.y;
            }
        }
    }
    result
}

pub fn translate_paths(paths: &Paths64, dx: i64, dy: i64) -> Paths64 {
    let mut result = paths.clone();
    for path in &mut result {
        for p in path.iter_mut() {
            p.x += dx;
            p.y += dy;
        }
    }
    result
}

#[derive(Clone, Copy, PartialEq, Debug, Default)]
pub struct PointD {
    pub x: f64,
    pub y: f64,
}

impl PointD {
    pub fn new(x: f64, y: f64) -> PointD {
        PointD { x, y }
    }
}

pub type PathD = Vec<PointD>;

// integer cross products (as in engine)
pub fn cross_product_3(pt1: Point64, pt2: Point64, pt3: Point64) -> f64 {
    // CrossProduct(pt1, pt2, pt3) = (pt2.x - pt1.x) * (pt3.y - pt2.y) - (pt2.y - pt1.y) * (pt3.x - pt2.x)
    (((pt2.x - pt1.x) as f64) * ((pt3.y - pt2.y) as f64)
        - ((pt2.y - pt1.y) as f64) * ((pt3.x - pt2.x) as f64)) as f64
}

pub fn dot_product_3(pt1: Point64, pt2: Point64, pt3: Point64) -> f64 {
    // DotProduct(pt1, pt2, pt3) = (pt2.x - pt1.x) * (pt3.x - pt2.x) + (pt2.y - pt1.y) * (pt3.y - pt2.y)
    ((pt2.x - pt1.x) as f64) * ((pt3.x - pt2.x) as f64)
        + ((pt2.y - pt1.y) as f64) * ((pt3.y - pt2.y) as f64)
}

pub fn cross_product_pt(a: Point64, b: Point64) -> f64 {
    (a.x as f64) * (b.y as f64) - (b.x as f64) * (a.y as f64)
}

pub fn dot_product_pt(a: Point64, b: Point64) -> f64 {
    (a.x as f64) * (b.x as f64) + (a.y as f64) * (b.y as f64)
}

pub fn dot_product_d(a: PointD, b: PointD) -> f64 {
    a.x * b.x + a.y * b.y
}

pub fn cross_product_d(a: PointD, b: PointD) -> f64 {
    a.y * b.x - b.y * a.x
}

pub fn scale_path(paths: &Paths64) -> &Paths64 {
    paths
}

