pub const NIL: usize = usize::MAX;

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub struct Point64 {
    pub x: i64,
    pub y: i64,
}

impl Point64 {
    pub fn new(x: i64, y: i64) -> Point64 {
        Point64 { x, y }
    }
}

#[derive(Clone, Copy, Debug)]
pub struct PointD {
    pub x: f64,
    pub y: f64,
}

impl PointD {
    pub fn new(x: f64, y: f64) -> PointD {
        PointD { x, y }
    }
    pub fn negate(&mut self) {
        self.x = -self.x;
        self.y = -self.y;
    }
}

pub type Path64 = Vec<Point64>;
pub type Paths64 = Vec<Path64>;
pub type PathD = Vec<PointD>;

#[derive(Clone, Copy, Debug)]
pub struct Rect64 {
    pub left: i64,
    pub top: i64,
    pub right: i64,
    pub bottom: i64,
}

impl Rect64 {
    pub fn invalid() -> Rect64 {
        Rect64 {
            left: i64::MAX,
            top: i64::MAX,
            right: i64::MIN,
            bottom: i64::MIN,
        }
    }
}

/// std::nearbyint with default rounding mode (round half to even)
pub fn rint(x: f64) -> f64 {
    let t = x.trunc();
    if (x - t).abs() == 0.5 {
        if (t as i64) % 2 == 0 {
            t
        } else {
            t + x.signum()
        }
    } else {
        x.round()
    }
}

/// Point64 from PointD (Clipper2 Point<long>::Point<double> uses rounding)
pub fn point64_from_d(p: PointD) -> Point64 {
    Point64 {
        x: rint(p.x) as i64,
        y: rint(p.y) as i64,
    }
}

pub fn path64_from_d(p: &PathD) -> Path64 {
    p.iter().map(|&pt| point64_from_d(pt)).collect()
}

/// Clipper2 Area(Path64)
pub fn area(path: &Path64) -> f64 {
    let cnt = path.len();
    if cnt < 3 {
        return 0.0;
    }
    let mut a = 0.0f64;
    let mut prev = path[cnt - 1];
    for &cur in path.iter() {
        a += (prev.y + cur.y) as f64 * (prev.x - cur.x) as f64;
        prev = cur;
    }
    a * 0.5
}

/// Clipper2 GetBounds(Paths64)
pub fn get_bounds(paths: &Paths64) -> Rect64 {
    let mut r = Rect64::invalid();
    for path in paths {
        for p in path {
            if p.x < r.left {
                r.left = p.x;
            }
            if p.x > r.right {
                r.right = p.x;
            }
            if p.y < r.top {
                r.top = p.y;
            }
            if p.y > r.bottom {
                r.bottom = p.y;
            }
        }
    }
    r
}

pub fn translate_path(path: &Path64, dx: i64, dy: i64) -> Path64 {
    path.iter().map(|p| Point64::new(p.x + dx, p.y + dy)).collect()
}

pub fn translate_paths(paths: &Paths64, dx: i64, dy: i64) -> Paths64 {
    paths.iter().map(|p| translate_path(p, dx, dy)).collect()
}

/// C++ `std::cout << double` default formatting (%g, 6 significant digits)
pub fn format_g6(v: f64) -> String {
    if v == 0.0 {
        return if v.is_sign_negative() {
            "-0".to_string()
        } else {
            "0".to_string()
        };
    }
    if v.is_nan() {
        return "nan".to_string();
    }
    if v.is_infinite() {
        return if v < 0.0 { "-inf".to_string() } else { "inf".to_string() };
    }
    let s = format!("{:.5e}", v); // like "1.48927e4"
    let (mant, exp) = s.split_once('e').unwrap();
    let exp: i32 = exp.parse().unwrap();
    let neg = mant.starts_with('-');
    let digits: String = mant.chars().filter(|c| c.is_ascii_digit()).collect();
    // digits.len() == 6
    let sign = if neg { "-" } else { "" };
    if exp >= 6 || exp < -4 {
        let frac = digits[1..].trim_end_matches('0');
        let m = if frac.is_empty() {
            digits[..1].to_string()
        } else {
            format!("{}.{}", &digits[..1], frac)
        };
        format!(
            "{}{}e{}{:02}",
            sign,
            m,
            if exp < 0 { "-" } else { "+" },
            exp.abs()
        )
    } else {
        let int_len = exp + 1;
        let out = if int_len >= 6 {
            digits.clone()
        } else if int_len > 0 {
            let ip = &digits[..int_len as usize];
            let fp = digits[int_len as usize..].trim_end_matches('0');
            if fp.is_empty() {
                ip.to_string()
            } else {
                format!("{}.{}", ip, fp)
            }
        } else {
            let fp_full = format!("{}{}", "0".repeat((-int_len) as usize), digits);
            let fp = fp_full.trim_end_matches('0');
            format!("0.{}", fp)
        };
        format!("{}{}", sign, out)
    }
}

