// test20.rs — Rust reimplementation of test20.cpp (Clipper2 2.0.1 test program)
mod clipper;

use clipper::core::*;
use clipper::engine::*;
use clipper::offset::*;

/// Mimic std::stoi on argv[1]: skip whitespace, optional sign, digits.
/// Returns Err on invalid_argument / out_of_range (C++ would abort).
fn parse_stoi(s: &str) -> Result<i32, ()> {
    let b = s.as_bytes();
    let mut i = 0usize;
    while i < b.len() && matches!(b[i], b' ' | b'\t' | b'\n' | b'\x0b' | b'\x0c' | b'\r') {
        i += 1;
    }
    let mut sign: i64 = 1;
    if i < b.len() && (b[i] == b'+' || b[i] == b'-') {
        if b[i] == b'-' {
            sign = -1;
        }
        i += 1;
    }
    let start = i;
    let mut val: i64 = 0;
    while i < b.len() && b[i].is_ascii_digit() {
        val = val * 10 + (b[i] - b'0') as i64;
        if val > 2_147_483_648 {
            return Err(()); // out_of_range for int
        }
        i += 1;
    }
    if i == start {
        return Err(()); // invalid_argument
    }
    let v = sign * val;
    if v < i32::MIN as i64 || v > i32::MAX as i64 {
        return Err(()); // out_of_range
    }
    Ok(v as i32)
}

fn main() {
    let args: Vec<String> = std::env::args().collect();
    let complexity: i32 = if args.len() > 1 {
        match parse_stoi(&args[1]) {
            Ok(v) => v.min(5),
            Err(()) => {
                // mimic uncaught exception -> abort, no stdout
                std::process::exit(134);
            }
        }
    } else {
        3
    };

    // ---- build 3 geometry layers ----
    let pi = 3.1415926f64;
    let mut geometry_layers: Vec<Paths64> = Vec::new();

    // layer 1: circles and squares
    let mut layer1: Paths64 = Vec::new();
    for i in 0..complexity as i64 {
        let mut circle: Path64 = Vec::new();
        for j in 0..24i64 {
